package com.yeyamo_mobile.api.admin_service.event;
import java.time.Instant;import java.util.*;import org.springframework.stereotype.Component;import com.fasterxml.jackson.databind.ObjectMapper;
@Component public class AdminEventOutbox{private final AdminOutboxRepository repo;private final ObjectMapper mapper;public AdminEventOutbox(AdminOutboxRepository r,ObjectMapper m){repo=r;mapper=m;}public void partnerDecision(String type,UUID partnerId,UUID validationId,String comment,Integer riskScore,UUID validatedBy,String correlationId){Map<String,Object>payload=new LinkedHashMap<>();payload.put("partnerId",partnerId);payload.put("validationId",validationId);payload.put("reviewComment",comment);payload.put("riskScore",riskScore);payload.put("validatedBy",validatedBy);domainEvent(type,partnerId.toString(),payload,validatedBy.toString(),correlationId);}public void domainEvent(String type,String aggregateKey,Map<String,Object>payload,String actorId,String correlationId){try{UUID id=UUID.randomUUID();Instant now=Instant.now();Map<String,Object>event=new LinkedHashMap<>();event.put("eventId",id);event.put("eventType",type);event.put("eventVersion",1);event.put("occurredAt",now);event.put("producer","admin-service");event.put("correlationId",correlationId);event.put("actorId",actorId);event.put("payload",payload);AdminOutboxEvent row=new AdminOutboxEvent();row.setId(id);row.setAggregateId(UUID.nameUUIDFromBytes(aggregateKey.getBytes(java.nio.charset.StandardCharsets.UTF_8)));row.setEventType(type);row.setPayload(mapper.writeValueAsString(event));row.setOccurredAt(now);repo.save(row);}catch(Exception e){throw new IllegalStateException("Unable to create admin event",e);}}}
